public class InnerEndpointMonitoringConfigurationFactory(Action<Humidifier.EMRContainers.EndpointTypes.MonitoringConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.EMRContainers.EndpointTypes.MonitoringConfiguration>
{

    internal InnerEndpointS3MonitoringConfigurationFactory S3MonitoringConfigurationFactory { get; set; }

    internal InnerEndpointContainerLogRotationConfigurationFactory ContainerLogRotationConfigurationFactory { get; set; }

    internal InnerEndpointCloudWatchMonitoringConfigurationFactory CloudWatchMonitoringConfigurationFactory { get; set; }

    protected override Humidifier.EMRContainers.EndpointTypes.MonitoringConfiguration Create()
    {
        var monitoringConfigurationResult = CreateMonitoringConfiguration();
        factoryAction?.Invoke(monitoringConfigurationResult);

        return monitoringConfigurationResult;
    }

    private Humidifier.EMRContainers.EndpointTypes.MonitoringConfiguration CreateMonitoringConfiguration()
    {
        var monitoringConfigurationResult = new Humidifier.EMRContainers.EndpointTypes.MonitoringConfiguration();

        return monitoringConfigurationResult;
    }
    public override void CreateChildren(Humidifier.EMRContainers.EndpointTypes.MonitoringConfiguration result)
    {
        base.CreateChildren(result);

        result.S3MonitoringConfiguration ??= S3MonitoringConfigurationFactory?.Build();
        result.ContainerLogRotationConfiguration ??= ContainerLogRotationConfigurationFactory?.Build();
        result.CloudWatchMonitoringConfiguration ??= CloudWatchMonitoringConfigurationFactory?.Build();
    }

} // End Of Class

